  var rows=ppSpecialise(PP_SC.FAMROWS[k].map(function(r){return [r[0],r[1].slice(),r[2],r[3]];}), name);
  var counted=PP_SC.COUNTED.indexOf(k)>=0, piece=PP_SC.PER_PIECE[k];
